  "skill_name": "center-multigeometry",
  "category": "software-development",
  "version": "1.1.0",
  "description": "Use for structural risk maps / multi-geometry code scans.",
  "app_root": "../..",
  "spec_sources": [
    "../../docs/spec/10-skill-draft.md",
    "../../docs/spec/01-product-requirements.md",
    "../../docs/spec/06-reporting-and-cli.md"
  ],
